def find(lst, x):
    lo, hi = 0, len(lst) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if lst[mid] == x:
            return mid
        if lst[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
```

